import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Select } from 'antd';
import cn from 'classnames';

import { EFilters, useFilters } from 'features/Filters';

import styles from './LinksFilters.module.scss';

export interface ILinksFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const LinksFilters = ({ className, ...props }: ILinksFiltersProps) => {
	const { t } = useTranslation();
	const { sourcesOptions, offersOptions, sourcesIsFetching, offersIsFetching, onFilterChange, getALLFilterValues } =
		useFilters();

	return (
		<div {...props} className={cn(className, styles.filters)}>
			<Select
				size="small"
				mode="multiple"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.SOURCE_ID, value)}
				value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE_ID)}
				options={sourcesOptions}
				loading={sourcesIsFetching}
				disabled={sourcesIsFetching}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать площадку')}
				allowClear
			/>

			<Select
				size="small"
				mode="multiple"
				maxTagCount="responsive"
				onChange={(value) => onFilterChange(EFilters.OFFER_ID, value)}
				value={offersIsFetching ? null : getALLFilterValues(EFilters.OFFER_ID)}
				options={offersOptions}
				loading={offersIsFetching}
				disabled={offersIsFetching}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать оффер')}
				allowClear
			/>
		</div>
	);
};

export default LinksFilters;
