import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Divider, Drawer, Flex, Form, Typography } from 'antd';

import CutIcon from 'assets/images/icons/cut.svg?react';
import { IEditingLink, SubIds, useCreateShortLinkMutation } from 'entities/Link';
import { SourceLink } from 'entities/Source';
import { useDisableBodyScroll } from 'shared/hooks';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

interface IEditLinkDrawerProps extends HTMLAttributes<HTMLDivElement> {
	link: IEditingLink | null;
	setEditingLink: (link: IEditingLink | null) => void;
}

export const EditLinkDrawer: FC<IEditLinkDrawerProps> = ({ link, setEditingLink, ...props }) => {
	const { t } = useTranslation();
	const [affiliateLink, setAffiliateLink] = useState('');
	const [shortLink, setShortLink] = useState('');
	const [createShortLink, { data, isLoading, isSuccess }] = useCreateShortLinkMutation();

	useDisableBodyScroll(!!link);

	useEffect(() => {
		if (isSuccess) {
			setShortLink(data?.short_link);
		}
	}, [isSuccess, data?.short_link]);

	useEffect(() => {
		setAffiliateLink('');
		setShortLink('');
	}, [link?.link]);

	if (!link) return null;

	return (
		<Drawer
			{...props}
			title={t('Редактирование информации')}
			width={450}
			open={!!link}
			onClose={() => setEditingLink(null)}>
			<Flex vertical gap={24}>
				<Flex vertical gap={8}>
					<Typography.Title level={4} style={{ margin: 0 }}>
						{link.offer}
					</Typography.Title>
					<Typography.Text type="secondary">{link.source}</Typography.Text>
				</Flex>

				<Divider style={{ margin: 0 }} />

				<Form.Item label={t('Ваша партнерская ссылка')} layout="vertical">
					<SourceLink
						link={link.link}
						maxWidth={1000}
						onCopy={() =>
							sendYmEvent({
								event: EYmEvents.CLICK_COPY_LINK,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.LINKS],
								o2: [EYmEventsO2.LINKS, EYmEventsO2.ADD_SUBID],
								o4: link.link,
								pi: link.offer,
								wi: link.source,
							})
						}
					/>
				</Form.Item>

				<SubIds affiliateLink={link?.link} setAffiliateLink={setAffiliateLink} />

				<Divider style={{ margin: 0 }} />

				<SourceLink
					label={
						<span>
							{t('Обновленная ссылка')} <Typography.Text type="secondary">({t('SubID включен')})</Typography.Text>
						</span>
					}
					link={affiliateLink}
					maxWidth={1000}
					disabled={!affiliateLink}
					onCopy={() =>
						sendYmEvent({
							event: EYmEvents.CLICK_COPY_LINK,
							o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.LINKS],
							o2: [EYmEventsO2.LINKS, EYmEventsO2.ADD_SUBID],
							o4: affiliateLink,
							pi: link.offer,
							wi: link.source,
						})
					}
				/>

				{shortLink && (
					<SourceLink
						label={
							<span>
								{t('Короткая ссылка')} <Typography.Text type="secondary">({t('SubID включен')})</Typography.Text>
							</span>
						}
						link={isLoading ? t('Сокращаем') + '...' : shortLink}
						maxWidth={1000}
						onCopy={() =>
							sendYmEvent({
								event: EYmEvents.CLICK_COPY_SHORTLINK,
								o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.LINKS],
								o2: [EYmEventsO2.LINKS, EYmEventsO2.ADD_SUBID],
								o4: shortLink,
								pi: link.offer,
								wi: link.source,
							})
						}
					/>
				)}

				<Button
					color="default"
					variant="dashed"
					disabled={isLoading}
					onClick={() => createShortLink({ affiliate_link: affiliateLink || link.link })}
					icon={<CutIcon />}
					iconPosition="end">
					{t('Сократить ссылку')}
				</Button>

				<Flex justify="space-between" gap={16}>
					<Button onClick={() => setEditingLink(null)}>{t('Закрыть')}</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
