import { FC, HTMLAttributes } from 'react';

import { Flex, Tooltip, Typography } from 'antd';

import { CELL_MAX_WIDTH, IAffiliateSubLink } from 'entities/Link';
import { PLATFORM_TYPES } from 'shared/consts';

interface ILinkPlatformProps extends HTMLAttributes<HTMLDivElement> {
	link: IAffiliateSubLink;
}

export const LinkPlatform: FC<ILinkPlatformProps> = ({ link, ...props }) => {
	return (
		<Flex {...props} gap={32} align="center">
			{PLATFORM_TYPES?.[link.platform_type as keyof typeof PLATFORM_TYPES] && (
				<Tooltip title={PLATFORM_TYPES?.[link.platform_type as keyof typeof PLATFORM_TYPES]?.name}>
					{PLATFORM_TYPES?.[link.platform_type as keyof typeof PLATFORM_TYPES]?.icon}
				</Tooltip>
			)}
			<Typography.Text type="secondary" style={{ maxWidth: CELL_MAX_WIDTH }} ellipsis={{ tooltip: link.platform_url }}>
				{link.platform_url}
			</Typography.Text>
		</Flex>
	);
};
