import { FC, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, ButtonProps, Flex, Modal, Typography } from 'antd';

import { IAffiliateLegalData } from 'entities/Link/model/types';
import { SourceLink } from 'entities/Source';

interface ILinkEridProps extends ButtonProps {
	link: string;
	legalData?: IAffiliateLegalData;
}

export const LinkErid: FC<ILinkEridProps> = ({ link, legalData, ...props }) => {
	const { t } = useTranslation();
	const [isOpened, setIsOpened] = useState(false);

	const getErid = () => {
		try {
			const url = new URL(link || '');

			return url.searchParams.get('erid') || '';
		} catch (e) {
			return '';
		}
	};

	return (
		<>
			<Button {...props} onClick={() => setIsOpened(true)}>
				{t('Маркировка')}
			</Button>

			<Modal
				open={isOpened}
				width={450}
				footer={null}
				closable={true}
				maskClosable={true}
				onCancel={() => setIsOpened(false)}>
				<Flex vertical gap={20}>
					<Typography.Title level={4} style={{ margin: 0 }}>
						{t('Маркировка рекламы')}
					</Typography.Title>

					<Flex gap={16} style={{ width: '100%' }}>
						<div style={{ width: '30%' }}>
							<SourceLink
								link={getErid()}
								label={
									<Typography.Text type="secondary" style={{ fontSize: 12 }}>
										{t('ERID отдельно:')}
									</Typography.Text>
								}
								labelGap={8}
								maxWidth={500}
							/>
						</div>
						<div style={{ flexGrow: 1, width: 'calc(70% - 16px)' }}>
							<SourceLink
								link={link}
								label={
									<Typography.Text type="secondary" style={{ fontSize: 12 }}>
										{t('ERID в составе ссылки:')}
									</Typography.Text>
								}
								labelGap={8}
								maxWidth={500}
							/>
						</div>
					</Flex>

					<SourceLink
						link={`${t('Реклама')}. ${legalData?.legal_name ? legalData.legal_name + '.' : ''} ${legalData?.inn || ''} ${getErid()}`}
						label={
							<Typography.Text type="secondary" style={{ fontSize: 12 }}>
								{t('Для маркировки:')}
							</Typography.Text>
						}
						labelGap={8}
						maxWidth={500}
					/>

					<Flex justify="end">
						<Button onClick={() => setIsOpened(false)}>{t('Закрыть')}</Button>
					</Flex>
				</Flex>
			</Modal>
		</>
	);
};
