import { FC, HTMLAttributes, ReactNode, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { ConfigProvider, Flex, Table, TableColumnsType } from 'antd';

import { EditLinkDrawer, getLink, IEditingLink, useGetLinksListQuery } from 'entities/Link';
import { EFilters, LinksFilters, useFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';

interface SubDataType {
	key: React.Key;
	platform: ReactNode;
	landing: ReactNode;
	affiliate_link: ReactNode;
	button: ReactNode;
}

interface DataType {
	key: React.Key;
	source: ReactNode;
	offer: ReactNode;
	links: ReactNode;
	childrens: SubDataType[];
}

interface ILinksListProps extends HTMLAttributes<HTMLDivElement> {}

export const LinksList: FC<ILinksListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [editingLink, setEditingLink] = useState<IEditingLink | null>(null);
	const [searchParams, setSearchParams] = useSearchParams();
	const { data, isFetching } = useGetLinksListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;
	const { getALLFilterValues } = useFilters();
	const sourceFilters = getALLFilterValues(EFilters.SOURCE_ID);
	const offerFilters = getALLFilterValues(EFilters.OFFER_ID);

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'source',
			key: 'source',
			title: t('Площадка'),
			defaultSortOrder: getDefaultSortOrder('source', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'offer',
			key: 'offer',
			title: t('Оффер'),
			defaultSortOrder: getDefaultSortOrder('offer', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'links',
			key: 'links',
			title: t('Ссылка'),
		},
	];

	const subColumns: TableColumnsType<SubDataType> = [
		{
			dataIndex: 'platform',
			key: 'platform',
			title: t('Площадка'),
			defaultSortOrder: getDefaultSortOrder('platform', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'landing',
			key: 'landing',
			title: t('Оффер'),
			defaultSortOrder: getDefaultSortOrder('landing', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'affiliate_link',
			key: 'affiliate_link',
			title: t('Ссылка'),
		},
		{
			dataIndex: 'button',
			key: 'button',
			width: 164,
		},
	];

	const dataSource = hasData
		? data?.results?.map<DataType>((link) => {
				return getLink(link, link.source.uuid + link.offer.uuid, (editingLink: IEditingLink) =>
					setEditingLink(editingLink),
				);
			})
		: [];

	return (
		<Flex vertical gap={20} {...props} className={className}>
			{isFetching && <OverlayLoader />}

			<LinksFilters />

			{!hasData && !isFetching && <EmptyState title={t('Пока нет ссылок')} />}

			{hasData && (
				<>
					<Table<DataType>
						columns={columns}
						dataSource={dataSource}
						bordered={false}
						scroll={{ x: 'max-content' }}
						pagination={false}
						showSorterTooltip={false}
						onChange={getTableSorter<DataType>(searchParams, setSearchParams)}
						expandable={{
							expandedRowRender: (record) => (
								<ConfigProvider
									theme={{ components: { Table: { headerBorderRadius: 0, colorBgContainer: '#f5f5f5' } } }}>
									<Table<SubDataType>
										columns={subColumns}
										dataSource={record.childrens}
										showHeader={false}
										bordered={false}
										scroll={{ x: 'max-content' }}
										pagination={false}
										showSorterTooltip={false}
									/>
								</ConfigProvider>
							),
							rowExpandable: (record) => !!record.childrens,
							defaultExpandedRowKeys:
								sourceFilters.length === 1 && offerFilters.length === 1
									? [sourceFilters[0] + offerFilters[0]]
									: undefined,
							indentSize: 0,
						}}
					/>

					<Pagination count={data?.count || 1} />
				</>
			)}

			<EditLinkDrawer link={editingLink} setEditingLink={setEditingLink} />
		</Flex>
	);
};
