import { IShortLinkRequest, IShortLinkResponse, TAffiliateLinksList } from 'entities/Link';
import { commonApi } from 'shared/api/commonApi';
import { getCookie } from 'shared/utils/getCookie';

export const linksApi = commonApi.injectEndpoints({
	endpoints: (builder) => ({
		getLinksList: builder.query<TAffiliateLinksList, string>({
			query: (params) => ({
				url: `my_links/${params ? '?' : ''}${params}`,
			}),
		}),
		createShortLink: builder.mutation<IShortLinkResponse, IShortLinkRequest>({
			query(body) {
				return {
					url: `short_link/`,
					headers: { 'X-Csrftoken': getCookie('csrftoken') },
					method: 'POST',
					body,
				};
			},
		}),
	}),
	overrideExisting: false,
});

export const { useGetLinksListQuery, useCreateShortLinkMutation } = linksApi;
