import { ChangeEvent, FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Input, Typography } from 'antd';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import { SUBIDS_MAX_COUNT } from 'entities/Link';
import { addSubIdsToUrl } from 'features/ShortLink/utils/addSubIdsToUrl';

interface ISubIdsProps extends HTMLAttributes<HTMLDivElement> {
	affiliateLink: string;
	setAffiliateLink: (link: string) => void;
}

export const SubIds: FC<ISubIdsProps> = ({ affiliateLink, setAffiliateLink, ...props }) => {
	const { t } = useTranslation();
	const [subIds, setSubIds] = useState<Record<string, string>>({ '1': '' });
	const onSubIdChange = (e: ChangeEvent<HTMLInputElement>, key: string) => {
		const newValues = { ...subIds, [key]: e.target.value };
		setSubIds(newValues);
		setAffiliateLink(addSubIdsToUrl(affiliateLink, newValues));
	};

	return (
		<Flex {...props} vertical align="start" gap={8}>
			<div>
				<Typography.Text>{t('Добавьте до {{count}} SubID', { count: SUBIDS_MAX_COUNT })}</Typography.Text>{' '}
				<Typography.Text type="secondary">({t('опционально')})</Typography.Text>
			</div>

			<Flex vertical gap={8} style={{ width: '100%' }}>
				{Object.keys(subIds).map((key) => {
					return (
						<Input
							placeholder={`SubID ${key}`}
							value={subIds[key]}
							onChange={(e) => onSubIdChange(e, key)}
							allowClear
						/>
					);
				})}
			</Flex>

			{Object.keys(subIds).length < SUBIDS_MAX_COUNT && (
				<Button
					variant="text"
					color="primary"
					icon={<PlusIcon width={16} height={16} />}
					disabled={Object.keys(subIds).length >= SUBIDS_MAX_COUNT}
					onClick={() => setSubIds({ ...subIds, [Object.keys(subIds).length + 1]: '' })}>
					{t('Добавить SubID')}
				</Button>
			)}
		</Flex>
	);
};
