import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';

import { CELL_MAX_WIDTH, IAffiliateLink } from 'entities/Link';

interface ILinkSourceProps extends HTMLAttributes<HTMLDivElement> {
	link: IAffiliateLink;
}

export const LinkSource: FC<ILinkSourceProps> = ({ link, ...props }) => {
	const { t } = useTranslation();

	const { source, affiliate_links } = link;

	const platformType = affiliate_links[0].platform_type;
	const expandable = affiliate_links.length > 1;

	const platformsCount = new Set(affiliate_links.map(({ platform_type }) => platform_type)).size;

	return (
		<Flex {...props} vertical>
			<Typography.Text style={{ maxWidth: CELL_MAX_WIDTH }} ellipsis={{ tooltip: source.name }}>
				{source.name}
			</Typography.Text>
			<Typography.Text
				type="secondary"
				style={{ fontSize: 12, maxWidth: CELL_MAX_WIDTH }}
				ellipsis={!expandable && { tooltip: affiliate_links[0].platform_url }}>
				{!expandable && affiliate_links[0].platform_url}
				{expandable && !!platformType && `${t('Платформы')}: ${platformsCount}`}
				{expandable && !platformType && `${t('Рекламных сетей')}: ${affiliate_links.length}`}
			</Typography.Text>
		</Flex>
	);
};
