import { FC, HTMLAttributes, ReactNode, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, theme, Typography } from 'antd';
import cn from 'classnames';

import { CopyButton } from 'shared/ui';

import styles from './SourceLink.module.scss';

interface ISourceLinkProps extends HTMLAttributes<HTMLDivElement> {
	link: string;
	label?: ReactNode;
	labelGap?: number;
	maxWidth?: number;
	disabled?: boolean;
	onCopy?: () => void;
}

export const SourceLink: FC<ISourceLinkProps> = ({
	className,
	link,
	label,
	disabled,
	labelGap = 8,
	maxWidth = 200,
	style,
	onCopy,
	...props
}) => {
	const { t } = useTranslation();
	const {
		token: { colorBorder, colorPrimary, colorBgBase, colorBgContainerDisabled },
	} = theme.useToken();

	const [copied, setCopied] = useState(false);

	return (
		<Flex vertical gap={labelGap} {...props} style={{ ...style, maxWidth: maxWidth + 60 }}>
			{label}

			<Flex
				gap={8}
				align="center"
				justify="space-between"
				style={{
					borderColor: colorBorder,
					backgroundColor: disabled ? colorBgContainerDisabled : colorBgBase,
					width: '100%',
				}}
				className={cn(className, styles.sourceId)}>
				<Typography.Text
					ellipsis={{ tooltip: link }}
					style={{ maxWidth: maxWidth, color: disabled ? colorBorder : colorPrimary }}>
					{copied ? t('Скопировано!') : link}
				</Typography.Text>
				<CopyButton
					text={link}
					size="small"
					variant="text"
					color="primary"
					style={{ width: 32, height: 32, minWidth: 32 }}
					onCopied={(copied) => {
						setCopied(copied);
						copied && onCopy?.();
					}}
					withoutTooltip
					disabled={disabled}
				/>
			</Flex>
		</Flex>
	);
};
