import { FC, HTMLAttributes } from 'react';

import { Button, Flex } from 'antd';

import { IAffiliateLegalData, LinkErid } from 'entities/Link';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

interface ILinkButtonsProps extends HTMLAttributes<HTMLDivElement> {
	link: string;
	legalData?: IAffiliateLegalData;
	onEdit: () => void;
	sourceUuid: string;
	offerUUid: string;
}

export const LinkButtons: FC<ILinkButtonsProps> = ({ link, onEdit, sourceUuid, offerUUid, legalData, ...props }) => {
	return (
		<Flex {...props} gap={8}>
			<LinkErid link={link} legalData={legalData} />
			<Button
				onClick={() => {
					sendYmEvent({
						event: EYmEvents.CLICK_ADD_SUBID,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.LINKS],
						o2: EYmEventsO2.LINKS,
						pi: sourceUuid,
						wi: offerUUid,
					});
					onEdit();
				}}>
				SubID
			</Button>
		</Flex>
	);
};
