import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';

import { CELL_MAX_WIDTH, IAffiliateSubLink } from 'entities/Link';

interface ILinkLandingProps extends HTMLAttributes<HTMLDivElement> {
	link: IAffiliateSubLink;
}

export const LinkLanding: FC<ILinkLandingProps> = ({ link }) => {
	const { t } = useTranslation();
	const isMain = !link.name;

	return (
		<Typography.Text
			type="secondary"
			strong={isMain}
			style={{ maxWidth: CELL_MAX_WIDTH, fontSize: 12 }}
			ellipsis={{ tooltip: link.name }}>
			{isMain ? t('Основной лендинг') : `${t('Лендинг')}: ${link.name}`}
		</Typography.Text>
	);
};
