import { Typography } from 'antd';

import {
	CELL_MAX_WIDTH,
	IAffiliateLink,
	IEditingLink,
	LinkButtons,
	LinkLanding,
	LinkPlatform,
	LinkPlatforms,
	LinkSource,
} from 'entities/Link';
import { SourceLink } from 'entities/Source';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { getMappedLinks, sendYmEvent } from 'shared/utils';

export const getLink = (link: IAffiliateLink, key: string, onEdit: (editingLink: IEditingLink) => void) => {
	const mappedLinks = getMappedLinks(link.affiliate_links);
	const { source, offer, legal_data } = link;

	return {
		key,
		source: <LinkSource link={link} />,
		offer: (
			<Typography.Text style={{ maxWidth: CELL_MAX_WIDTH }} ellipsis={{ tooltip: offer.name }}>
				{offer.name}
			</Typography.Text>
		),
		links: <LinkPlatforms links={mappedLinks} />,
		childrens: mappedLinks.map((link, i) => ({
			key: key + i.toString(),
			platform: <LinkPlatform link={link} />,
			landing: <LinkLanding link={link} />,
			affiliate_link: (
				<SourceLink
					link={link.tracking_link}
					onCopy={() =>
						sendYmEvent({
							event: EYmEvents.CLICK_COPY_LINK,
							o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.LINKS],
							o2: EYmEventsO2.LINKS,
							o4: link.tracking_link,
							pi: offer.uuid,
							wi: source.uuid,
						})
					}
				/>
			),
			button: (
				<LinkButtons
					link={link.tracking_link}
					legalData={legal_data}
					onEdit={() => onEdit({ source: source.name, offer: offer.name, link: link.tracking_link })}
					sourceUuid={source.uuid}
					offerUUid={offer.uuid}
				/>
			),
			childrens: null,
		})),
	};
};
