import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Tooltip, Typography } from 'antd';

import { IAffiliateSubLink } from 'entities/Link/model/types';
import { PLATFORM_TYPES } from 'shared/consts';

interface ILinkPlatformsProps extends HTMLAttributes<HTMLDivElement> {
	links: IAffiliateSubLink[];
}

export const LinkPlatforms: FC<ILinkPlatformsProps> = ({ links }) => {
	const { t } = useTranslation();

	const platforms = [...new Set(links.map(({ platform_type }) => platform_type))];

	return (
		<Flex gap={16} align="center">
			<Typography.Text type="secondary">
				{t('Ссылки')}: {links.length}
			</Typography.Text>

			<span style={{ lineHeight: 0 }}>
				{platforms.map((platform) => (
					<Tooltip title={PLATFORM_TYPES?.[platform as keyof typeof PLATFORM_TYPES]?.name}>
						{PLATFORM_TYPES?.[platform as keyof typeof PLATFORM_TYPES]?.icon}
					</Tooltip>
				))}
			</span>
		</Flex>
	);
};
